  for (const event of events) {
    try {
      results.push(importer.accept(event));
    } catch (err) {
      error = err;
      break;
    }
  }
  if (!error) {
    try {
      importer.finish();
      results.push({ kind: "finish" });
    } catch (err) {
      error = err;
    }
  }
  return { results, error };
