    snapshot &&
    snapshot.keys.length === 2 &&
    snapshot.keys.includes("schema") &&
    snapshot.keys.includes("kind") &&
    dataValue(snapshot, "schema") === SESSION_MESSAGE_PROVENANCE_SCHEMA &&
    DURABLE_KINDS.has(dataValue(snapshot, "kind")),
