 * (`{ role, sourceEventId, sourceItemIndex, parts: [...] }`), `contexts` are
 * ancestor messages (`{ type, role, content, origin }`; origin null for system).
 * The closing `session_branch_complete` digest is recomputed to match the importer.
 */
function buildBranchEvents({
  startData = { provider: "test" },
  archives = [],
  contexts = [],
  complete = true,
}) {
  const events = [];
  events.push({ type: "session_start", data: { ...startData } });
  const branchData = {
    history: {
      schema: BRANCH_HISTORY_SCHEMA,
      sourceGeneration: hash64("gen"),
