return {
  accept(event) {
    index += 1;
    if (index === 1 && event.type === "session_start") {
      const data = { ...event.data };
      delete data[SESSION_GENERATION_AUTHORITY_FIELD];
      start = { type: event.type, data };
    }
    if (event.type === "session_branch" && event.data?.history != null) {
      const descriptor = event.data.history;
      require(
        index === 2 &&
          start &&
          !active &&
          [
            BRANCH_HISTORY_SCHEMA,
            BRANCH_HISTORY_SYSTEM_ORIGINS_SCHEMA,
          ].includes(descriptor.schema) &&
          hash(descriptor.sourceGeneration) &&
          integer(descriptor.totalMessages) &&
          integer(descriptor.contextMessageCount) &&
          descriptor.contextMessageCount <= 32768,
      );
      const coverage = descriptor.coverage;
      require(
        coverage?.kind === "from-origin"
          ? coverage.boundaryEvent === null && coverage.reason === null
          : coverage?.kind === "snapshot-boundary" &&
              hash(coverage.boundaryEvent) &&
              [
                "timeline-replacement",
                "context-snapshot",
                "branch-snapshot",
              ].includes(coverage.reason),
      );
      const digest = createHash("sha256").update(
        `[${JSON.stringify(start)},${JSON.stringify({ type: event.type, data: event.data })}`,
      );
      active = {
        descriptor,
        digest,
        rows: 0,
        contexts: 0,
        pending: null,
        textParts: [],
        textBytes: 0,
        textIdentity: null,
        contextStarted: false,
      };
      return { kind: "start", coverage };
    }
    if (!active) {
      if (
        [BRANCH_HISTORY_MESSAGE, BRANCH_HISTORY_ORIGIN].includes(
          event.type,
        ) ||
        (event.type === "session_branch_complete" &&
          event.data?.schemaVersion === 2)
      )
        invalid();
      return null;
    }
    const state = active;
    if (event.type === "session_branch_complete") {
      require(
        !state.pending &&
          state.textParts.length === 0 &&
          state.rows === state.descriptor.totalMessages &&
          state.contexts === state.descriptor.contextMessageCount &&
          event.data?.schemaVersion === 2 &&
          event.data.messageCount === state.contexts &&
          event.data.inputDigest ===
            `sha256:${state.digest.update("]").digest("hex")}`,
      );
      active = null;
      return { kind: "complete" };
    }
    state.digest.update(
      `,${JSON.stringify({ type: event.type, data: event.data })}`,
    );
    if (event.type === BRANCH_HISTORY_MESSAGE) {
      const row = event.data;
      require(
        !state.contextStarted &&
          state.rows < state.descriptor.totalMessages &&
          ["user", "assistant", "tool"].includes(row?.role) &&
          typeof row.text === "string" &&
          row.text.length <= 128 * 1024 &&
          row.part === state.textParts.length &&
          typeof row.last === "boolean" &&
          hash(row.sourceEventId) &&
          integer(row.sourceItemIndex),
      );
      const identity = `${row.role}:${row.sourceEventId}:${row.sourceItemIndex}`;
      require(state.textIdentity === null || state.textIdentity === identity);
      state.textIdentity = identity;
      state.textBytes += Buffer.byteLength(row.text);
      require(
        state.textBytes <= 16 * 1024 * 1024 && state.textParts.length < 256,
      );
      state.textParts.push(row.text);
      if (!row.last) return { kind: "archive-part" };
      const message = { role: row.role, content: state.textParts.join("") };
      state.textParts = [];
      state.textBytes = 0;
      state.textIdentity = null;
      state.rows += 1;
      return { kind: "archive", message };
    }
    if (
      ["user_message", "assistant_message", "system"].includes(event.type)
    ) {
      require(
        !state.pending &&
          state.textParts.length === 0 &&
          state.rows === state.descriptor.totalMessages &&
          state.contexts < state.descriptor.contextMessageCount &&
          event.data?.role ===
            {
              user_message: "user",

                assistant_message: "assistant",
                system: "system",
              }[event.type],
        );
        state.contextStarted = true;
        state.pending = event.data;
        return { kind: "context" };
      }
      if (event.type === BRANCH_HISTORY_ORIGIN) {
        const message = state.pending;
        const origin = event.data?.origin;
        require(
          message && event.data.messageDigest === branchMessageDigest(message),
        );
        require(
          origin === null
            ? message.role === "system"
            : origin &&
                integer(origin.first) &&
                integer(origin.last) &&
                origin.first <= origin.last &&
                origin.last < state.rows &&
                (message.role !== "system" ||
                  (state.descriptor.schema ===
                    BRANCH_HISTORY_SYSTEM_ORIGINS_SCHEMA &&
                    getDurableSystemMessageProvenance(
                      decodeVerifiedPersistedMessage(message),
                    ))),
        );
        state.contexts += 1;
        state.pending = null;
        return { kind: "origin", message, origin };
      }
      invalid();
    },
    finish() {
      if (active) invalid();
    },
  };
}

/**
 * Fork history ownership — independent regression coverage for
 * packages/cli/src/lib/session-branch-history.js.
 *
 * Acceptance: two branches each restore a valid ancestor and their own
 * independent body text; content must not bleed in from another branch or from
 * events after the branch completes. These cases drive `createBranchHistoryImport`
 * directly (pure, deterministic event stream) so every guard is exercised
 * without filesystem, RNG, clock or git.
 */
import { describe, it, expect } from "vitest";
import { createHash } from "node:crypto";
import {
  BRANCH_HISTORY_SCHEMA,
  createBranchHistoryImport,
  branchMessageDigest,
} from "../../src/lib/session-branch-history.js";

const hash64 = (seed) => createHash("sha256").update(seed).digest("hex");

/**
 * Runs a stream through a fresh importer, recording every non-null accept()
 * result (e.g. { kind: "archive", message } / { kind: "origin", message,
 * origin } / { kind: "complete" }) and the first thrown error (if any). Then
 * calls finish(); a branch left active is reported as an error, matching the
 * parser's `finish()` guard.
 */
function run(events) {
  const importer = createBranchHistoryImport();
  const results = [];
  let error = null;
  for (const event of events) {
    try {
      const result = importer.accept(event);
      if (result && result.kind) results.push(result);
    } catch (err) {
      error = err;
      break;
    }
  }
  if (!error) {
    try {
      importer.finish();
    } catch (err) {
      error = err;
    }
  }
  return { importer, results, error };
}

/** Asserts the given call rejects with the branch-history-invalid code. */
function expectInvalid(fn) {
  let err = null;
  try {
    fn();
  } catch (e) {
    err = e;
  }
  expect(err).not.toBeNull();
  expect(err.code).toBe("SESSION_BRANCH_HISTORY_INVALID");
  return err;
}

/**
 * Builds the event stream for one branch import. `archives` are body message
 * rows (`{ role, sourceEventId, sourceItemIndex, parts: [...] }`), `contexts`
 * are ancestor messages (`{ type, role, content, origin }`; origin null for
 * system). The closing `session_branch_complete` inputDigest is recomputed
 * exactly as the importer does: start and branch as a prefix, then every
 * following event as a suffix, then a closing "]".
 */
function buildBranchEvents({
  startData = { provider: "test" },
  archives = [],
  contexts = [],
  complete = true,
}) {
  const events = [];
  events.push({ type: "session_start", data: { ...startData } });
  const branchData = {
    history: {
      schema: BRANCH_HISTORY_SCHEMA,
      sourceGeneration: hash64("gen"),
      totalMessages: archives.length,
      contextMessageCount: contexts.length,
      coverage: { kind: "from-origin", boundaryEvent: null, reason: null },
    },
  };
  events.push({ type: "session_branch", data: branchData });
  for (const a of archives) {
    a.parts.forEach((text, partIndex) => {
      events.push({
        type: "session_history_message",
        data: {
          role: a.role,
          text,
          part: partIndex,
          last: partIndex === a.parts.length - 1,
          sourceEventId: a.sourceEventId,
          sourceItemIndex: a.sourceItemIndex,
        },
      });
    });
  }
  for (const c of contexts) {
    const message = { role: c.role, content: c.content };
    events.push({ type: c.type, data: message });
    events.push({
      type: "session_history_origin",
      data: { messageDigest: branchMessageDigest(message), origin: c.origin },
    });
  }
  if (complete) {
    const start = { type: "session_start", data: { ...startData } };
    const parts = [
      `[${JSON.stringify(start)},${JSON.stringify({
        type: events[1].type,
        data: events[1].data,
      })}`,
    ];
    for (let i = 2; i < events.length; i++) {
      parts.push(
        `,${JSON.stringify({ type: events[i].type, data: events[i].data })}`,
      );
    }
    parts.push("]");
    events.push({
      type: "session_branch_complete",
      data: {
        schemaVersion: 2,
        messageCount: contexts.length,
        inputDigest: `sha256:${createHash("sha256")
          .update(parts.join(""))
          .digest("hex")}`,
      },
    });
  }
  return events;
}

describe("createBranchHistoryImport — fork history ownership", () => {
  it("two separate forks each restore their own valid ancestor and body", () => {
    const eventsA = buildBranchEvents({
      archives: [
        {
          role: "user",
          sourceEventId: hash64("a-e"),
          sourceItemIndex: 0,
          parts: ["body A"],
        },
      ],
      contexts: [
        {
          type: "assistant_message",
          role: "assistant",
          content: "ancestor A",
          origin: { first: 0, last: 0 },
        },
      ],
    });
    const eventsB = buildBranchEvents({
